  if (inputDate && currentDate.getTime() > inputDate.getTime()) {
    dateString = `${inputDate.getFullYear()}-${(inputDate.getMonth() + 1).toString().padStart(2, '0')}-${inputDate.getDate()}`;
  } else {
    dateString = `${currentDate.getFullYear()}-${(currentDate.getMonth() + 1).toString().padStart(2, '0')}-${currentDate.getDate()}`;
  }

  fetch('/api/set/reminder?text=' + encodeURIComponent(reminderText) + '&date=' + encodeURIComponent(dateString))
