    def calculator(self, expression):
        # Evaluate an arithmetic expression using Python's syntax
        # Replace this function with your own logic to evaluate the expression.
        variables = {
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: a / b,
            '//': lambda a, b: a // b,
            '**': lambda a, b: a ** b,
            '%': lambda a, b: a % b
        }

        parts = expression.split(' ')
        result = float(parts[0])
        for i, part in enumerate(parts[1:]):
            operation = parts[i+1]
            if operation in variables:
                result = variables[operation](float(result), float(parts[i+2]))
            else:
                raise ValueError("Unrecognized operator: " + operation)

        return str(result)

