function send_email(to: string, subject: string, body: string): void {
    console.log("send email to " + to + " with subject " + subject + " and body " + body);
    const emailHeaders = {
        From: 'ambari@yourwebsite.com',
        To: to,
        Subject: subject,
        'X-CC-REPLY-TO': 'ambari@yourwebsite.com',
        'X-Mailer': 'AMQP',
    };
    const emailBody = 'body'
    const requestBody = JSON.stringify({ "x-amqp": "Via HTTP", "headers": emailHeaders, "body": { "body": body }});
    fetch('http://minio.mydomain.com/' + 'amqp.rabbitmq' , {
        method: 'POST',
        body: requestBody,
        headers: {
            'Content-Type': 'application/json',
        },
    }).then(response => {
        if (response.ok) {
            return response.text();
        } else {
            throw new Error('Error sending mail: ' + response.status);
        }
    }).then(data => console.log(data))
        .catch(error => console.log('Error sending mail: ', error));
}
