	const url = `users/contacts/${encodeURIComponent(
		escape(query)
	)}/${
		M TextInputType.HIDDENGET_STRING
	}`

	return axios
		.get(url)
		.then((result: AxiosResponse<OwnDatabase>) => {
			return result.data.fd_member_list;
		})
		.catch((error:AxiosError) => {
			throw new Error(error.message);
		});
}

function deleteCalendarEvent(event_id: string) {
	const url = `calendars/${event_id}`

	return axios
		.delete(url)
		.then((result:AxiosResponse) => {
			return findCalendarsByDestinationId(result.data.fd_destination.id).then((calendars) => {
				return [
					...calendars,
					...calendars.filter((cal) => cal.destination_id !== result.data.fd_destination.id),
				];
			});
		});
}

function getStockPrice(symbol: string) {
	const url = `symbols/${symbol}`

	return axios
		.get(url)
		.then((result:AxiosResponse) => {
			return result.data.stock_detail;
		})
		.catch((error:AxiosError) => {
			throw new Error(error.message);
		});
}

