	<script>
	function search_contacts(query) {
		const xhr = new XMLHttpRequest();
		xhr.onreadystatechange = function () {
			if (xhr.readyState === 4 && xhr.status === 200) {
				const responseData = JSON.parse(xhr.responseText);
				let results = [];
				for (const contact of responseData) {
					if (contact.name.includes(query)) {
						results.push({
							name: contact.name,
							email: contact.email,
							phone: contact.phone,
							team: contact.team
						});
					}
				}
				return { results };
			}
		};
		xhr.open('GET', `/api/user/contacts?query=${encodeURIComponent(query)}`, true);
		xhr.send();
	};
