import static java.util.Arrays.stream;

public class JavaQueueDemo {

    public static void main(final String[] arg) {

        final Queue<Integer> queue = new ArrayDeque<>();

        for (final int i : stream(range(10, 100)).collect(toList())) {
            queue.offer(i);
        }

        System.out.println("Initial: " + queue);
        System.out.println("\nDequeueing and printing:");
        for (final String s: stream(queue).filter(e -> e  % 10 != 0).collect(toList()).iterator()) {
            System.out.println(" -->  " + s);
            queue.remove(s);
            System.out.println("Current:  " + queue);
        }
        System.out.println("\nRerunning...");
        for (final String s: queue.iterator()) {
            System.out.println(" --> TOTAL: " + s);
        }
    }
}

