function sendMessage(selectedClass, messageSubmitFormUrl, messageInputEl, messageSubmitButtonEl, submitResultButton) {
  [selectedClass].classList.add('active');

  const messageInput = document.getElementById(messageInputEl);
  const messageSubmitButton = document.getElementById(messageSubmitButtonEl);
  const submitResult = document.getElementById(submitResultButton);

  messageInput.value = messageInput.value || '';
  messageSubmitButton.disabled = messageInput.value === '';

  const httpHeaderValue = 'application/x-www-form-urlencoded; charset=utf-8';
  const formData = new FormData();

  formData.append('message', messageInput.value);
  formData.append('referer.href', 'http://127.0.0.1:49012');

  const fetchOptions = {
    method: 'POST',
    headers: {
      [httpHeaderValue]: `https://example.com/${messageSubmitFormUrl}`
    },
    body: formData
  };
  fetch(`http://127.0.0.1:8000/c/${messageSubmitFormUrl}`, fetchOptions)
    .then(response => response.json())
    .then(data => {
      console.log('Controller Response:', data);
      submitResult.innerHTML = data.submitResultText || JSON.stringify('Submitted on server.');
      [selectedClass].classList.remove('active');
    })
    .catch(error => {
      console.error('Error:', error);
      [selectedClass].classList.remove('active');
      submitResult.innerHTML = JSON.stringify('An error occurred.');
    });
}
</script>

